private val state = new AtomicReference[State](Closed)

def authorize(order: Order)(using ec: ExecutionContext): Future[Receipt] =
  if (!admit()) Future.failed(CircuitOpen("payments"))
  else api.authorize(order).andThen { case outcome => record(outcome) }

private def admit(): Boolean =
  @tailrec def go(s: State): Boolean = s match
    case Open(until) if System.nanoTime() < until => false        // cooling down
    case s: Open => if (state.compareAndSet(s, HalfOpen(0))) true else go(state.get)
    case _ => true
  go(state.get)
